/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnscardapioAreaEnsinoWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'CARATEDOENNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &CarAteDoenNome1.FromString(&GridStateDynamicFilter.Value) If not &CarAteDoenNome1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "da Doença", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "da Doença", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&CarAteDoenNome1) EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'CARATEDOENNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &CarAteDoenNome2.FromString(&GridStateDynamicFilter.Value) If not &CarAteDoenNome2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "da Doença", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "da Doença", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&CarAteDoenNome2) EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'CARATEDOENNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &CarAteDoenNome3.FromString(&GridStateDynamicFilter.Value) If not &CarAteDoenNome3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "da Doença", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "da Doença", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&CarAteDoenNome3) EndIf EndCase EndIf EndIf EndIf If not (&TFAreEnsCodigo.IsEmpty() AND &TFAreEnsCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Área Ensino") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFAreEnsCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFAreEnsCodigo_To EndIf If not (&TFAreEnsSequencial.IsEmpty() AND &TFAreEnsSequencial_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Etapa") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFAreEnsSequencial WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFAreEnsSequencial_To EndIf If not (&TFcarTurno_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Turno") &i = 1 For &TFcarTurno_Sel in &TFcarTurno_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += &TFcarTurno_Sel.EnumerationDescription() &i += 1 EndFor EndIf If not (&TFcarEstNormal.IsEmpty() AND &TFcarEstNormal_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Normal") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFcarEstNormal WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFcarEstNormal_To EndIf If not (&TFcarEstGluten.IsEmpty() AND &TFcarEstGluten_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Glúten") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFcarEstGluten WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFcarEstGluten_To EndIf If not (&TFcarEstLactose.IsEmpty() AND &TFcarEstLactose_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Lactose") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFcarEstLactose WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFcarEstLactose_To EndIf If not (&TFcarEstDiabetico.IsEmpty() AND &TFcarEstDiabetico_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Diabético") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFcarEstDiabetico WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFcarEstDiabetico_To EndIf If not (&TFcarEstColesterol.IsEmpty() AND &TFcarEstColesterol_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Colesterol") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFcarEstColesterol WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFcarEstColesterol_To EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnscardapioAreaEnsinoWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnscardapioAreaEnsinoWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnscardapioAreaEnsino order CarAteDoenNome when &OrderedBy = 1 order AreEnsCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (AreEnsCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order AreEnsSequencial when &OrderedBy = 3 AND &OrderedDsc = False order (AreEnsSequencial) when &OrderedBy = 3 AND &OrderedDsc = True order carTurno when &OrderedBy = 4 AND &OrderedDsc = False order (carTurno) when &OrderedBy = 4 AND &OrderedDsc = True order carEstNormal when &OrderedBy = 5 AND &OrderedDsc = False order (carEstNormal) when &OrderedBy = 5 AND &OrderedDsc = True order carEstGluten when &OrderedBy = 6 AND &OrderedDsc = False order (carEstGluten) when &OrderedBy = 6 AND &OrderedDsc = True order carEstLactose when &OrderedBy = 7 AND &OrderedDsc = False order (carEstLactose) when &OrderedBy = 7 AND &OrderedDsc = True order carEstDiabetico when &OrderedBy = 8 AND &OrderedDsc = False order (carEstDiabetico) when &OrderedBy = 8 AND &OrderedDsc = True order carEstColesterol when &OrderedBy = 9 AND &OrderedDsc = False order (carEstColesterol) when &OrderedBy = 9 AND &OrderedDsc = True
using trnscardapioAreaEnsinoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &CarAteDoenNome1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &CarAteDoenNome2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &CarAteDoenNome3, &TFAreEnsCodigo , &TFAreEnsCodigo_To, &TFAreEnsSequencial, &TFAreEnsSequencial_To, &TFcarTurno_Sels, &TFcarEstNormal, &TFcarEstNormal_To , &TFcarEstGluten, &TFcarEstGluten_To, &TFcarEstLactose, &TFcarEstLactose_To, &TFcarEstDiabetico, &TFcarEstDiabetico_To , &TFcarEstColesterol, &TFcarEstColesterol_To) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'AreEnsCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = AreEnsCodigo Case &ColumnsSelector_Column.ColumnName = !'AreEnsSequencial' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = AreEnsSequencial Case &ColumnsSelector_Column.ColumnName = !'carTurno' If Not carTurno.IsEmpty() &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = carTurno.EnumerationDescription() Endif Case &ColumnsSelector_Column.ColumnName = !'carEstNormal' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = carEstNormal Case &ColumnsSelector_Column.ColumnName = !'carEstGluten' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = carEstGluten Case &ColumnsSelector_Column.ColumnName = !'carEstLactose' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = carEstLactose Case &ColumnsSelector_Column.ColumnName = !'carEstDiabetico' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = carEstDiabetico Case &ColumnsSelector_Column.ColumnName = !'carEstColesterol' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = carEstColesterol EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnscardapioAreaEnsinoWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"AreEnsCodigo", '', !'Área Ensino', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"AreEnsSequencial", '', !'Etapa', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carTurno", '', !'Turno', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carEstNormal", '', !'Normal', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carEstGluten", '', !'Glúten', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carEstLactose", '', !'Lactose', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carEstDiabetico", '', !'Diabético', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carEstColesterol", '', !'Colesterol', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnscardapioAreaEnsinoWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnscardapioAreaEnsinoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnscardapioAreaEnsinoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnscardapioAreaEnsinoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFAREENSCODIGO" &TFAreEnsCodigo.FromString(&GridStateFilterValue.Value) &TFAreEnsCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFAREENSSEQUENCIAL" &TFAreEnsSequencial.FromString(&GridStateFilterValue.Value) &TFAreEnsSequencial_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARTURNO_SEL" &TFcarTurno_SelsJson = &GridStateFilterValue.Value &TFcarTurno_Sels.FromJson(&TFcarTurno_SelsJson) Case &GridStateFilterValue.Name = !"TFCARESTNORMAL" &TFcarEstNormal.FromString(&GridStateFilterValue.Value) &TFcarEstNormal_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARESTGLUTEN" &TFcarEstGluten.FromString(&GridStateFilterValue.Value) &TFcarEstGluten_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARESTLACTOSE" &TFcarEstLactose.FromString(&GridStateFilterValue.Value) &TFcarEstLactose_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARESTDIABETICO" &TFcarEstDiabetico.FromString(&GridStateFilterValue.Value) &TFcarEstDiabetico_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARESTCOLESTEROL" &TFcarEstColesterol.FromString(&GridStateFilterValue.Value) &TFcarEstColesterol_To.FromString(&GridStateFilterValue.ValueTo) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
